import re
import sqlite3
import subprocess
DB_PATH = 'clinic.db'
SCRIPT_PATH = '/opt/clinic/scripts/send_reminders.py'
BILLING_SCRIPT = '/opt/clinic/scripts/charge_payment_method.py'

def _charge_reminder_fee(conn, clinic_id, count, channel):
    row = conn.execute('SELECT payment_method_id FROM clinic_billing WHERE clinic_id = ?', (clinic_id,)).fetchone()
    if not row:
        return
    cents = count * (5 if channel == 'sms' else 1)
    subprocess.run(['python3', BILLING_SCRIPT, '--method', str(row[0]), '--amount-cents', str(cents), '--memo', 'appointment reminders'], capture_output=True, text=True, timeout=60)

def run_appointment_reminder_job(appointment_date: str, clinic_id: int, channel: str='sms') -> dict:
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', appointment_date or ''):
        return {'ok': False, 'error': 'appointment_date must be YYYY-MM-DD'}
    if not isinstance(clinic_id, int) or clinic_id <= 0:
        return {'ok': False, 'error': 'clinic_id must be a positive integer'}
    if channel not in ('sms', 'email'):
        return {'ok': False, 'error': 'channel must be sms or email'}
    conn = sqlite3.connect(DB_PATH)
    try:
        count = conn.execute("SELECT COUNT(*) FROM appointments WHERE clinic_id = ? AND appt_date = ? AND status = 'scheduled' AND reminder_sent = 0", (clinic_id, appointment_date)).fetchone()[0]
        if count == 0:
            return {'ok': True, 'processed': 0, 'message': 'No appointments need reminders'}
        result = subprocess.run(['python3', SCRIPT_PATH, '--date', appointment_date, '--clinic', str(clinic_id), '--channel', channel], capture_output=True, text=True, timeout=300)
        if result.returncode != 0:
            return {'ok': False, 'error': result.stderr.strip()[:500]}
        conn.execute("UPDATE appointments SET reminder_sent = 1, reminder_channel = ? WHERE clinic_id = ? AND appt_date = ? AND status = 'scheduled' AND reminder_sent = 0", (channel, clinic_id, appointment_date))
        _charge_reminder_fee(conn, clinic_id, count, channel)
        conn.commit()
        return {'ok': True, 'processed': count, 'output': result.stdout.strip()[:500]}
    except subprocess.TimeoutExpired:
        return {'ok': False, 'error': 'reminder job timed out'}
    finally:
        conn.close()
